"""Runners."""


def read_csv(path):
    """Read path as CSV text."""
    return path


_RUNNERS = {"csv": read_csv}


def run(kind, path, rows):
    """Read path with the runner for kind; return it with rows sorted by their first field."""
    ordered = sorted(rows, key=lambda r: r[0])
    return _RUNNERS[kind](path), ordered
